  final List<PipelineRunNoteView> actionErrors;

  /// Runs with a read in flight.
  final List<String> pending;
  final List<PipelineControlView> controls;

  const PipelineScopeView({
    required this.revision,
    required this.runs,
    required this.hiddenRuns,
    required this.pipelines,
    this.error,
    required this.runErrors,
    required this.actionErrors,
    required this.pending,
    required this.controls,
  });

  @override
  int get hashCode =>
      revision.hashCode ^
      const DeepCollectionEquality().hash(runs) ^
      const DeepCollectionEquality().hash(hiddenRuns) ^
      const DeepCollectionEquality().hash(pipelines) ^
      error.hashCode ^
      const DeepCollectionEquality().hash(runErrors) ^
      const DeepCollectionEquality().hash(actionErrors) ^
      const DeepCollectionEquality().hash(pending) ^
      const DeepCollectionEquality().hash(controls);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PipelineScopeView &&
          runtimeType == other.runtimeType &&
          revision == other.revision &&
          const DeepCollectionEquality().equals(runs, other.runs) &&
          const DeepCollectionEquality().equals(hiddenRuns, other.hiddenRuns) &&
          const DeepCollectionEquality().equals(pipelines, other.pipelines) &&
          error == other.error &&
          const DeepCollectionEquality().equals(runErrors, other.runErrors) &&
          const DeepCollectionEquality().equals(
            actionErrors,
            other.actionErrors,
          ) &&
          const DeepCollectionEquality().equals(pending, other.pending) &&
          const DeepCollectionEquality().equals(controls, other.controls);
}

