@freezed
sealed class PipelinesIntent with _$PipelinesIntent {
  const PipelinesIntent._();

  /// The session became usable or ended: reads and controls in flight
  /// are forgotten; a connect reloads every watched worktree.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.setConnected({required bool connected}) =
      PipelinesIntent_SetConnected;

  /// Shows `chat`'s worktree and loads it; `token` names the watch for
  /// [`Self::Release`].
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.watch({
    required ChatRefView chat,
    required int token,
  }) = PipelinesIntent_Watch;

  /// Ends the watch `token`.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.release({required int token}) =
      PipelinesIntent_Release;

  /// Reads the worktree's runs and pipelines (one load at a time).
  ///
  /// Resolves when settled: the load finished (its failure is the view's
  /// error).
  const factory PipelinesIntent.load({required ChatRefView chat}) =
      PipelinesIntent_Load;

  /// Reads one run.
  ///
  /// Resolves when settled: the read finished; the outcome carries the
  /// run, or none when it failed (the failure is the run's error).
  const factory PipelinesIntent.get_({
    required ChatRefView chat,
    required String id,
  }) = PipelinesIntent_Get;

  /// Selects a step and reads its output tail onto the run.
  ///
  /// Resolves when settled: the read finished or failed.
  const factory PipelinesIntent.log({
    required ChatRefView chat,
    required String id,
    required String jobId,
    required String stepId,
  }) = PipelinesIntent_Log;

  /// Forgets the run's selected step.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.clearLogSelection({
    required ChatRefView chat,
    required String id,
  }) = PipelinesIntent_ClearLogSelection;

  /// Cancels, retries or resumes a run, sent at most once while one is in
  /// flight for it.
  ///
  /// Resolves when settled: the desktop answered (or the control
  /// failed into the view's action error).
  const factory PipelinesIntent.control({
    required ChatRefView chat,
    required String id,
    required PipelineAction action,
  }) = PipelinesIntent_Control;

  /// Clears a run's action error.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.clearActionError({
    required ChatRefView chat,
    required String id,
  }) = PipelinesIntent_ClearActionError;

  /// Reads a pipeline's dispatch form.
  ///
  /// Resolves when settled: the outcome carries the form, or the
  /// failure.
  const factory PipelinesIntent.form({
    required ChatRefView chat,
    required String pipelineId,
    required PipelineOrigin origin,
  }) = PipelinesIntent_Form;

  /// Starts a pipeline: `pipelines:execute` at most once. An unconfirmed
  /// start blocks the next start of that pipeline.
  ///
  /// Resolves when settled: the run was started and read (the outcome
  /// carries its id), or the start failed.
  const factory PipelinesIntent.start({
    required ChatRefView chat,
    required String pipelineId,
    required PipelineOrigin origin,
    required List<PipelineInputValue> inputs,
  }) = PipelinesIntent_Start;

  /// Reads a step's output or the run's report.
  ///
  /// Resolves when settled: the outcome carries the document, or the
  /// failure.
  const factory PipelinesIntent.content({
    required ChatRefView chat,
    required String id,
    required PipelineContentSource source,
  }) = PipelinesIntent_Content;

  /// A feed's run panels follow `chat` (none for a chat without a
  /// worktree): they watch its worktree and read the runs its turns
  /// link. `token` names the follower.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.follow({
    required int token,
    ChatRefView? chat,
    required bool online,
  }) = PipelinesIntent_Follow;

  /// Ends the follower `token`.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.unfollow({required int token}) =
      PipelinesIntent_Unfollow;

  /// The work drawer `token` shows `chat` (`update`).
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.drawerUpdate({
    required int token,
    required ChatRefView chat,
    required bool online,
    required bool ready,
  }) = PipelinesIntent_DrawerUpdate;

  /// Clears the drawer's action errors and reads again.
  ///
  /// Resolves when settled: the read it started or joined finished.
  const factory PipelinesIntent.drawerRetry({required int token}) =
      PipelinesIntent_DrawerRetry;

  /// Runs an item's action.
  ///
  /// Resolves when settled: the action and the read after it finished
  /// (a failure is the drawer's error).
  const factory PipelinesIntent.drawerAct({
    required int token,
    required String itemId,
    required WorkAction action,
    required bool notifySubscriber,
  }) = PipelinesIntent_DrawerAct;

  /// Ends the drawer `token`.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.drawerClose({required int token}) =
      PipelinesIntent_DrawerClose;

  /// Stops the pipelines.
  ///
  /// Resolves when applied.
  const factory PipelinesIntent.close() = PipelinesIntent_Close;
}

